#include <cstdio>
#include <cstring>
#include <cmath>
#include <cstdlib>
#include <vector>
#include <string>
#include <algorithm>
#include <queue>
#include <stack>
#include <deque>
#include <map>
#include <set>
#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){int n;scanf("%d",&n);
if(n<=3){printf("%d\n",n-1);return 0;}
vector<long long>dp(n+1,0);dp[1]=1;
for(int i=2;i<=n;++i){long long best=i;
for(int j=1;j<i;++j)best=max(best,dp[j]*(i-j));
dp[i]=best;}
printf("%lld\n",dp[n]);return 0;}

